import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import API from '../services/api';

export default function UploadDocument() {
  const [form, setForm] = useState({ title: '', category: '', department: '', tags: '', notes: '' });
  const [file, setFile] = useState(null);
  const [categories, setCategories] = useState([]);
  const [newCategory, setNewCategory] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    API.get('/categories').then(r => setCategories(r.data)).catch(() => {});
  }, []);

  const handleAddCategory = async () => {
    if (!newCategory.trim()) return;
    try {
      const { data } = await API.post('/categories', { name: newCategory });
      setCategories([...categories, data]);
      setForm({ ...form, category: data._id });
      setNewCategory('');
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to create category');
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!file) return setError('Please select a file');
    setError(''); setSuccess(''); setLoading(true);
    try {
      const fd = new FormData();
      Object.entries(form).forEach(([k, v]) => fd.append(k, v));
      fd.append('file', file);
      await API.post('/documents', fd, { headers: { 'Content-Type': 'multipart/form-data' } });
      setSuccess('Document uploaded successfully!');
      setTimeout(() => navigate('/documents'), 1500);
    } catch (err) {
      setError(err.response?.data?.message || 'Upload failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.container}>
      <h2 style={styles.heading}>Upload Document</h2>
      {error && <p style={styles.error}>{error}</p>}
      {success && <p style={styles.success}>{success}</p>}
      <form onSubmit={handleSubmit} style={styles.form}>
        <label style={styles.label}>Title *</label>
        <input style={styles.input} value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} required />

        <label style={styles.label}>Category</label>
        <select style={styles.input} value={form.category} onChange={e => setForm({ ...form, category: e.target.value })}>
          <option value="">-- Select Category --</option>
          {categories.map(c => <option key={c._id} value={c._id}>{c.name}</option>)}
        </select>
        <div style={styles.row}>
          <input style={{ ...styles.input, flex: 1, marginBottom: 0 }} placeholder="New category name" value={newCategory}
            onChange={e => setNewCategory(e.target.value)} />
          <button type="button" onClick={handleAddCategory} style={styles.addBtn}>+ Add</button>
        </div>

        <label style={styles.label}>Department *</label>
        <input style={styles.input} value={form.department} onChange={e => setForm({ ...form, department: e.target.value })} required />

        <label style={styles.label}>Tags (comma separated)</label>
        <input style={styles.input} placeholder="e.g. finance, 2024, report" value={form.tags}
          onChange={e => setForm({ ...form, tags: e.target.value })} />

        <label style={styles.label}>Version Notes</label>
        <input style={styles.input} value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} />

        <label style={styles.label}>File * (PDF, DOCX, XLSX, JPG — max 10MB)</label>
        <input style={styles.input} type="file" accept=".pdf,.docx,.xlsx,.jpg,.jpeg"
          onChange={e => setFile(e.target.files[0])} required />

        <button style={styles.btn} type="submit" disabled={loading}>
          {loading ? 'Uploading...' : 'Upload Document'}
        </button>
      </form>
    </div>
  );
}

const styles = {
  container: { padding: '24px', maxWidth: '600px', margin: '0 auto' },
  heading: { color: '#1a237e', marginBottom: '20px' },
  form: { background: '#fff', padding: '24px', borderRadius: '8px', boxShadow: '0 1px 6px rgba(0,0,0,0.1)' },
  label: { display: 'block', fontSize: '13px', fontWeight: '600', marginBottom: '4px', color: '#333' },
  input: { display: 'block', width: '100%', padding: '9px', marginBottom: '14px', border: '1px solid #ccc', borderRadius: '4px', boxSizing: 'border-box', fontSize: '14px' },
  btn: { width: '100%', padding: '10px', background: '#1a237e', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer', fontSize: '15px' },
  error: { color: '#c62828', background: '#ffebee', padding: '8px', borderRadius: '4px', marginBottom: '12px' },
  success: { color: '#2e7d32', background: '#e8f5e9', padding: '8px', borderRadius: '4px', marginBottom: '12px' },
  row: { display: 'flex', gap: '8px', marginBottom: '14px' },
  addBtn: { padding: '9px 14px', background: '#00695c', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer', whiteSpace: 'nowrap' }
};
